    private static readonly Dictionary<string, string> _dataUris =
        _svgBodies.ToDictionary(
            kv => kv.Key,
            kv => "data:image/svg+xml;base64," + Convert.ToBase64String(Encoding.UTF8.GetBytes(
                "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"#ffffff\">" + kv.Value + "</svg>")),
            StringComparer.OrdinalIgnoreCase);

    /// <summary>The dropdown keys, in display order.</summary>
    public static IReadOnlyList<string> Keys { get; } =
        new[] { "authentik", "keycloak", "google", "microsoft", "okta", "auth0", "discord", "github" };

    /// <summary>A ready <c>data:</c> URI for the key, or null when the key isn't bundled.</summary>
    public static string? TryGet(string? key)
        => !string.IsNullOrWhiteSpace(key) && _dataUris.TryGetValue(key.Trim(), out var uri) ? uri : null;
}
